/// Report from a bucket rotation operation
class RotationReport {
  /// Total objects processed
  final int total;

  /// Objects successfully rotated
  final int rotated;

  /// Objects skipped (already current)
  final int skipped;

  /// Objects that failed rotation
  final int failed;

  /// Details of failures
  final List<RotationFailure> failures;

  const RotationReport({
    required this.total,
    required this.rotated,
    required this.skipped,
    required this.failed,
    required this.failures,
  });

  /// Check if all rotations succeeded
  Future<bool> isSuccess() =>
      RustLib.instance.api.crateApiTypesRotationReportIsSuccess(that: this);

  /// Get success rate as percentage
  Future<double> successRate() =>
      RustLib.instance.api.crateApiTypesRotationReportSuccessRate(that: this);

  @override
  int get hashCode =>
      total.hashCode ^
      rotated.hashCode ^
      skipped.hashCode ^
      failed.hashCode ^
      failures.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RotationReport &&
          runtimeType == other.runtimeType &&
          total == other.total &&
          rotated == other.rotated &&
          skipped == other.skipped &&
          failed == other.failed &&
          failures == other.failures;
}

/// Share mode for creating share tokens
