/// Progress of an upload operation
class UploadProgress {
  /// Bytes uploaded so far
  final BigInt bytesUploaded;

  /// Total bytes to upload
  final BigInt totalBytes;

  /// Current part number
  final int currentPart;

  /// Total number of parts
  final int totalParts;

  /// Percentage complete (0.0 - 100.0)
  final double percentage;

  const UploadProgress({
    required this.bytesUploaded,
    required this.totalBytes,
    required this.currentPart,
    required this.totalParts,
    required this.percentage,
  });

  // HINT: Make it `#[frb(sync)]` to let it become the default constructor of Dart class.
  /// Create a new progress struct
  static Future<UploadProgress> newInstance({
    required BigInt bytesUploaded,
    required BigInt totalBytes,
    required int currentPart,
    required int totalParts,
  }) => RustLib.instance.api.crateApiTypesUploadProgressNew(
    bytesUploaded: bytesUploaded,
    totalBytes: totalBytes,
    currentPart: currentPart,
    totalParts: totalParts,
  );

  @override
  int get hashCode =>
      bytesUploaded.hashCode ^
      totalBytes.hashCode ^
      currentPart.hashCode ^
      totalParts.hashCode ^
      percentage.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UploadProgress &&
          runtimeType == other.runtimeType &&
          bytesUploaded == other.bytesUploaded &&
          totalBytes == other.totalBytes &&
          currentPart == other.currentPart &&
          totalParts == other.totalParts &&
          percentage == other.percentage;
}
